C547_R = [("  function chDiscTick(dt) {                    // c220: 처음 발견 — 나·동료 시야에 처음 들어온 빨강 5명 · 경찰 2명까지\n    if (chDiscR >= CH_DISC_N && chDiscO >= CH_DISC_O && chDiscY >= CH_DISC_Y) return;\n    if ((chDiscT -= dt) > 0) return; chDiscT = 0.1;\n    for (const c of bodies) {\n      if (c.kind !== 'citizen' || c.disc || c.boss || !(c.hp > 0)) continue;\n      const red = c.attacker && c.vig && chDiscR < CH_DISC_N, cop = c.police && !c.military && c.street && chDiscR < CH_DISC_N;   /* c238: 배회 경찰만 */\n      const org = c.attacker && !c.vig && chDiscO < CH_DISC_O, yel = c.guard && !c.demoted && chDiscY < CH_DISC_Y;   // c262: 주황 4명 · 원래 노랑 3명\n      if (!red && !cop && !org && !yel) continue;\n      if (!(iSee(c) || zSeen(c))) continue;\n      c.disc = true;\n      if (org) { chDiscO++; chDemote(c, 'guard'); continue; }   // c262: 100% 노랑\n      if (yel) { chDiscY++; chDemote(c, ''); continue; }        // c262: 100% 하양\n      const r = Math.random(); if (r < 0.7) chDemote(c, r < 0.35 ? 'guard' : ''); else chDiscR++;   /* c252: 35 · 35 · 30 */   /* c246: 30% · 30% · 40% — 그대로 남은 수(빨강+경찰)를 센다 */\n    }", "  function chDiscTick(dt) {                    // c547: 처음 발견 보정 — 빨강 · 거리 경찰을 처음 볼 때 70% 확률로 바꾼다 (35% 노랑 · 35% 하양). 바뀐 빨강 2명 · 바뀐 경찰 2명이 되면 각각 끝. 주황 · 노랑은 안 바꾼다\n    if (chDiscR >= CH_DISC_N && chDiscP >= CH_DISC_N) return;\n    if ((chDiscT -= dt) > 0) return; chDiscT = 0.1;\n    for (const c of bodies) {\n      if (c.kind !== 'citizen' || c.disc || c.boss || !(c.hp > 0)) continue;\n      const red = c.attacker && c.vig && chDiscR < CH_DISC_N, cop = c.police && !c.military && c.street && chDiscP < CH_DISC_N;\n      if (!red && !cop) continue;\n      if (!(iSee(c) || zSeen(c))) continue;\n      c.disc = true;\n      const r = Math.random(); if (r < 0.7) { chDemote(c, r < 0.35 ? 'guard' : ''); if (red) chDiscR++; else chDiscP++; }\n    }"), ('  const CH_DISC_N = 4, CH_DISC_O = 2, CH_DISC_Y = 2;', '  const CH_DISC_N = 2;   /* c547: 바뀐 빨강 2 · 바뀐 경찰 2 (각각) */')]
